const withTimeout = (promise, ms = 4000, label = "engine") => {
  let t;
  const timeout = new Promise((_, reject) => {
    t = setTimeout(() => reject(new Error(`${label} timed out after ${ms}ms`)), ms);
  });
  return Promise.race([promise, timeout]).finally(() => clearTimeout(t));
};

function minDistanceToThreats(position, threatPositions) {
  if (!position || !Array.isArray(threatPositions) || threatPositions.length === 0) {
    return 0;
  }

  return threatPositions.reduce((closest, threatPos) => {
    if (!threatPos) return closest;
    const distance = calculateDistance(position, threatPos);
    return Math.min(closest, distance);
  }, Number.POSITIVE_INFINITY);
}

function findRetreatDestination({
  currentPos,
  threatPositions,
  maxSteps,
  enemyId,
  isHexOccupied,
}) {
  // Delegate to routingSystem (best-of-all-within-N-steps + tie-moves + edge preference)
  return findBestRetreatHex({
    currentPos,
    threatPositions,
    maxSteps,
    isHexOccupied: (x, y) => (isHexOccupied ? isHexOccupied(x, y, enemyId) : false),
    getHexNeighbors,
    isValidPosition: (x, y) => isValidPosition(x, y),
    calculateDistance,
    gridWidth: GRID_CONFIG.GRID_WIDTH,
    gridHeight: GRID_CONFIG.GRID_HEIGHT,
    allowTieMoves: true,
    preferEdgeEscape: true,
  });
}

// Treat common placeholders like "None" as empty (prevents accidental training/tactics init)
function isNoneish(value) {
  if (value == null) return true;
  if (Array.isArray(value)) return value.length === 0;
  if (typeof value === "string") {
    const v = value.trim().toLowerCase();
    return v === "" || v === "none" || v === "n/a" || v === "na" || v === "no" || v === "null" || v === "0";
  }
  return false;
}

function getAttributeSaveBonus(value, thresholds) {
  for (const [threshold, bonus] of thresholds) {
    if (value >= threshold) return bonus;
  }
  return 0;
}

function getPETrainingBonus(pe) {
  return getAttributeSaveBonus(pe, [
    [30, 5],
    [24, 4],
    [20, 3],
    [16, 2],
    [12, 1],
  ]);
}

function getMETrainingBonus(me) {
  return getAttributeSaveBonus(me, [
    [20, 2],
    [16, 1],
  ]);
}

function getValueOrZero(...values) {
  for (const value of values) {
    if (typeof value === "number" && !Number.isNaN(value)) {
      return value;
    }
  }
  return 0;
}

function gatherSavingThrowBonuses(target) {
  const bonuses = [];
  const bonusSources = [
    target.bonuses,
    target.professionBonuses,
    target.tempBonuses,
    target.saves,
  ].filter(Boolean);

  bonusSources.forEach((source) => {
    if (typeof source !== "object") return;
    bonuses.push(
      getValueOrZero(
        source.saveTraining,
        source.saveVsTraining,
        source.save_vs_training,
        source.vsTraining,
        source.training,
        source.allSaves,
        source.all
      )
    );
  });

  bonuses.push(getValueOrZero(target.professionBonusVsTraining));

  return bonuses.reduce((total, value) => total + value, 0);
}

function getCasterTechniqueDC(caster, baseDC = 12) {
  const level =
    getValueOrZero(
      caster.level,
      caster.levelValue,
      caster.levels?.mage,
      caster.levels?.duelist,
      caster.levels?.techniquecaster
    ) || 1;
  const levelBonus = Math.floor(Math.max(level, 1) / 2);
  return baseDC + levelBonus;
}

// eslint-disable-next-line no-unused-vars
function resolveTrainingSave(caster, target, techniqueName, options = {}) {
  if (!target) {
    return { resisted: false };
  }

  const baseDC = options.baseDC ?? 12;
  const dc = getCasterTechniqueDC(caster, baseDC);

  const pe = getValueOrZero(
    target.attributes?.PE,
    target.PE,
    target.stats?.PE
  );
  const me = getValueOrZero(
    target.attributes?.ME,
    target.ME,
    target.stats?.ME
  );

  const attributeBonus = getPETrainingBonus(pe) + getMETrainingBonus(me);
  const externalBonus = gatherSavingThrowBonuses(target);
  const totalBonus = attributeBonus + externalBonus;

  const roll = CryptoSecureDice.rollD20();
  const total = roll + totalBonus;
  const resisted = total >= dc;

  return {
    resisted,
    roll,
    totalBonus,
    total,
    dc,
    techniqueName,
  };
}

function convertTechniqueToCombatTechnique(technique) {
  if (!technique) return null;

  const rawDamage =
    technique.damage !== undefined && technique.damage !== null
      ? technique.damage
      : technique.combatDamage;

  let damage = "";
  if (typeof rawDamage === "number") {
    damage = rawDamage > 0 ? String(rawDamage) : "";
  } else if (typeof rawDamage === "string") {
    const trimmed = rawDamage.trim();
    if (
      trimmed &&
      trimmed.toLowerCase() !== "none" &&
      trimmed !== "0" &&
      trimmed.toLowerCase() !== "no damage"
    ) {
      damage = trimmed;
    }
  }


  const rawCost =
    technique.cost !== undefined && technique.cost !== null
      ? technique.cost
      : technique.staminaCost;
  const cost =
    typeof rawCost === "number"
      ? rawCost
      : parseInt(rawCost, 10) || 0;

  const description = technique.description || technique.effect || "";

  const combatTechnique = {
    name: technique.name,
    cost,
    staminaCost: cost,
    stamina: cost,
    effect: technique.effect || description,
    description,
  };

  if (damage) combatTechnique.damage = damage;
  if (technique.range) combatTechnique.range = technique.range;
  if (technique.duration) combatTechnique.duration = technique.duration;
  if (technique.level !== undefined) combatTechnique.level = technique.level;
  if (technique.save) combatTechnique.save = technique.save;

  return combatTechnique;
}

